class AppShellProfileAction extends StatefulWidget {
  const AppShellProfileAction({super.key});

  @override
  State<AppShellProfileAction> createState() => _AppShellProfileActionState();
}

class _AppShellProfileActionState extends State<AppShellProfileAction> {
  Uint8List? _avatarBytes;
  String _profileKey = '';

  @override
  void initState() {
    super.initState();
    ProfileAvatarCache.revision.addListener(_handleAvatarChanged);
    _loadAvatar();
  }

  @override
  void didUpdateWidget(covariant AppShellProfileAction oldWidget) {
    super.didUpdateWidget(oldWidget);
    _loadAvatar();
  }

  @override
  void dispose() {
    ProfileAvatarCache.revision.removeListener(_handleAvatarChanged);
    super.dispose();
  }

  void _handleAvatarChanged() {
    _loadAvatar(force: true);
  }

  Future<void> _loadAvatar({bool force = false}) async {
    final profile = AppSession.instance.profile;
    final key = profile == null
        ? ''
        : '${profile.accessRole?.name ?? profile.role.name}:${profile.ref}:${profile.avatarUrl}';
    if (!force && key == _profileKey) {
      return;
    }
    _profileKey = key;
    final bytes =
        profile == null ? null : await ProfileAvatarCache.ensureCached(profile);
    if (!mounted || key != _profileKey) {
      return;
    }
    setState(() {
      _avatarBytes = bytes;
    });
  }

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final localizations = Localizations.of<AppLocalizations>(
      context,
      AppLocalizations,
    );
    return Semantics(
      button: true,
      label: localizations?.profileTitle ?? 'Profile',
      onLongPressHint: localizations?.accountSwitchHint,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: () => Navigator.of(context).pushNamed(AppRoutes.profile),
        onLongPress: () {
          unawaited(HapticFeedback.mediumImpact());
          showAccountSwitcherSheet(context);
        },
        child: SizedBox(
          width: 38,
          height: 38,
          child: Center(
            child: _avatarBytes == null || _avatarBytes!.isEmpty
                ? Container(
                    width: 38,
                    height: 38,
                    decoration: BoxDecoration(
                      color: scheme.onPrimaryContainer,
                      shape: BoxShape.circle,
                    ),
                    child: Icon(
                      Icons.person_rounded,
                      size: AppTheme.headerActionIconSize,
                      color: scheme.primaryContainer,
                    ),
                  )
                : ClipOval(
                    child: Image.memory(
                      _avatarBytes!,
                      width: 38,
                      height: 38,
                      fit: BoxFit.cover,
                      cacheWidth: 96,
                      cacheHeight: 96,
                      filterQuality: FilterQuality.low,
                      gaplessPlayback: true,
                    ),
                  ),
          ),
        ),
      ),
    );
  }
}

